open class Person(val name: String) {
    var age = 0
        set(value) {
            if (value >= 0) {
                field = value
            } else {
                field = 0
            }
        }

    val remainingLifeYears: Int
        // Let’s stay optimistic and follow the example of Master Yoda.
        get() = 900 - age

    init {
        age = 0
    }

    fun speak() {
        println("Hi, I am $name and I am $age years old and have $remainingLifeYears years left")
    }

    fun listen() {
        // Read one line and repeat it with a short comment.
        val input = readln()
        println("You said: $input")
    }
}

class Student(name: String, val grade: Int) : Person(name) {
    init {
        age = (6..18).random()
    }

    fun study() {
        val subject = listOf("Kotlin", "Math", "Science").random()
        var minutes = (20..60).random()
        minutes += 5
        println("$name studies $subject for $minutes minutes")
    }
}

class People {
    val members = mutableListOf<Person>()
    var selected: Person? = null

    init {
        val initialMembers = listOf(Person("Alice"), Student("Ben", 7))
        for (member in initialMembers) {
            members.add(member)
        }
        selected = members.random()
    }

    fun addPerson(person: Person) {
        members.add(person)
    }

    fun greetSelected() {
        selected?.speak()
        val selectedName = selected?.name ?: "Nobody"
        println("Selected person: $selectedName")
    }

    fun listenToSelected() {
        val person = selected ?: members.random()
        person.listen()
    }
}
